<script setup>
import { computed, ref, watch } from 'vue'
import WorkspaceDialog from './WorkspaceDialog.vue'
import PublicQueueDisplay from './PublicQueueDisplay.vue'
import { ticketLabel } from '../lib/workspaceData.js'
const props = defineProps({ state: { type: Object, required: true }, publicState: { type: Object, required: true }, activeRows: { type: Array, default: () => [] } })
const emit = defineEmits(['refresh', 'action', 'reconcile', 'retry-public'])
const tab = ref('overview'), search = ref(''), dialog = ref(null), email = ref(''), role = ref('CASHIER'), enabled = ref(true), cashiers = ref([]), open = ref(false)
const snapshot = computed(() => props.state.status === 'ready' ? props.state.data : null)
const config = computed(() => snapshot.value?.configuration)
const locked = computed(() => !snapshot.value || props.state.busy || ['unknown', 'pending', 'blocked'].includes(props.state.phase))
const directory = computed(() => snapshot.value?.directory.filter(x => `${x.email || ''} ${x.id} ${x.role}`.toLowerCase().includes(search.value.trim().toLowerCase())) || [])
const counters = computed(() => [...(config.value?.counters || [])].sort((a, b) => a.number - b.number))
const fixedCodes = ['TP', 'SOA', 'PNEP', 'REF', 'ADJ']
const approval = (row, requestedRole) => row.approvals.some(a => a.role === requestedRole && Date.parse(a.expires_at) > Date.now())
const eligible = row => row.enabled && row.role === 'CASHIER' && row.verified_factors > 0 && approval(row, 'CASHIER')
const canSaveAccount = computed(() => dialog.value?.kind === 'account' && !locked.value && dialog.value.row.id !== props.state.actor
  && (!enabled.value || role.value === 'STUDENT' || dialog.value.row.verified_factors > 0 && approval(dialog.value.row, role.value)))
const emailValid = computed(() => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim()) && email.value.trim().length <= 254)
const targetByEmail = computed(() => snapshot.value?.directory.find(x => x.email === email.value.trim().toLowerCase()))
const assignments = id => (config.value?.staff_assignments || []).filter(a => a.account_id === id).map(a => counters.value.find(c => c.id === a.counter_id)?.number).filter(Boolean).join(', ') || 'None'
function editAccount(row) { dialog.value = { kind: 'account', row }; role.value = row.role; enabled.value = row.enabled }
function editCounter(row) { dialog.value = { kind: 'counter', row }; open.value = row.is_open; cashiers.value = config.value.staff_assignments.filter(a => a.counter_id === row.id).map(a => a.account_id) }
function request() { if (!locked.value && emailValid.value) { emit('action', 'request_staff_access', { p_email: email.value.trim().toLowerCase(), p_role: role.value }); dialog.value = null } }
function saveAccount() { if (canSaveAccount.value) { emit('action', 'set_account', { p_user: dialog.value.row.id, p_role: role.value, p_enabled: enabled.value }); dialog.value = null } }
function saveCounter() { if (!locked.value) { emit('action', 'configure_counter', { p_counter: dialog.value.row.id, p_open: open.value, p_services: [fixedCodes[dialog.value.row.number - 1]], p_cashiers: [...cashiers.value].sort() }); dialog.value = null } }
watch(() => props.state.status, next => { if (next !== 'ready') dialog.value = null })
</script>
<template>
  <article data-testid="admin-management">
    <div class="cqs-page-heading"><div><p class="cqs-eyebrow">Administrator workspace</p><h1>Campus service management</h1><p>Current database authorization, authenticator assurance and operator approval are checked on every protected request.</p></div><button type="button" class="cqs-button cqs-button-outline" :disabled="state.busy || state.status === 'loading'" @click="emit('refresh')">Refresh administration</button></div>
    <nav class="cqs-tabs" aria-label="Administrator sections"><button v-for="section in ['overview','staff','counters','reports']" :key="section" type="button" :aria-current="tab === section ? 'page' : undefined" :data-testid="'admin-tab-'+section" @click="tab=section">{{ {overview:'Overview',staff:'Staff management',counters:'Counter management',reports:'Reports / history'}[section] }}</button></nav>
    <p v-if="state.message" class="cqs-notice" role="status">{{ state.message }} <button v-if="state.phase === 'unknown'" class="cqs-link" type="button" :disabled="state.busy" @click="emit('reconcile')">Reconcile same request</button></p>
    <p v-if="!snapshot" class="cqs-notice" role="alert">{{ state.status === 'restricted' ? 'Staff approval or authenticator authorization is insufficient. Open Account security and request trusted operator review.' : state.status === 'loading' ? 'Loading current authorized administration…' : 'Protected administration is unavailable. No cached directory or staff controls are exposed.' }}</p>
    <template v-if="snapshot">
      <label class="cqs-field cqs-report-date">Report date (Asia/Manila)<input type="date" :value="snapshot.date" :disabled="state.busy" @change="emit('refresh',$event.target.value)"></label>
      <template v-if="tab==='overview'">
        <div class="cqs-stat-grid"><section v-for="key in ['total','waiting','called','served']" :key="key" class="cqs-card cqs-stat"><p>{{ {total:'Total tickets',waiting:'Waiting tickets',called:'Called tickets',served:'Served tickets'}[key] }}</p><strong>{{ snapshot.metrics[key] }}</strong><span>{{ snapshot.date }} · issuance date</span></section></div>
        <section class="cqs-card"><h2>Current operations</h2><p>{{ counters.filter(c=>c.is_open).length }} of 5 counters open. Queue day: {{ publicState.context ? publicState.context.queue_day_open ? 'Open' : 'Closed' : 'Unavailable' }} · {{ publicState.context?.business_date || 'Date unavailable' }}.</p><p class="cqs-caption">{{ activeRows.length }} authorized active tickets across queue dates. Account emails and student identities are excluded from queue projections.</p></section>
        <PublicQueueDisplay :state="publicState" embedded @retry="emit('retry-public')" />
      </template>
      <section v-if="tab==='staff'" class="cqs-card cqs-staff-panel">
        <div class="cqs-section-heading"><h2>Registered accounts</h2><button type="button" data-testid="add-staff" class="cqs-button cqs-button-primary" :disabled="locked" @click="email='';role='CASHIER';dialog={kind:'request'}">Add staff by email</button></div>
        <p class="cqs-caption">Only verified Google email bindings are shown. New emails create pending review requests, not invitations, accounts or permissions. The trusted operator must approve the exact UUID and identity before a staff role can be applied.</p>
        <label class="cqs-field">Search accounts<input v-model="search" type="search" placeholder="Verified email, UUID or role"></label>
        <div class="cqs-table-scroll" tabindex="0" aria-label="Authorized account directory"><table class="cqs-table"><thead><tr><th>Verified account</th><th>Role / access</th><th>Counters</th><th>MFA / operator approval</th><th>Action</th></tr></thead><tbody><tr v-for="row in directory" :key="row.id"><td><strong>{{ row.email || 'Verified Google email unavailable' }}</strong><small class="cqs-account-id">{{ row.id }}</small></td><td>{{ row.role }}<br>{{ row.enabled?'Enabled':'Disabled' }}</td><td>{{ assignments(row.id) }}</td><td>{{ row.verified_factors?'Verified factor enrolled':'Not enrolled' }}<br><span v-if="row.approvals.length">{{ row.approvals.map(a=>a.role+' until '+new Date(a.expires_at).toLocaleString()).join('; ') }}</span><span v-else>No current approval</span></td><td><button type="button" class="cqs-link" :disabled="locked || row.id===state.actor" @click="editAccount(row)">{{ row.id===state.actor?'Operator review required':'Review access' }}</button></td></tr><tr v-if="!directory.length"><td colspan="5">No registered accounts match.</td></tr></tbody></table></div>
        <h3>Pending staff review requests</h3><p class="cqs-caption">Latest 100 requests. Binding a request does not grant a role. No invitation email is sent.</p>
        <div class="cqs-table-scroll" tabindex="0" aria-label="Staff review requests"><table class="cqs-table"><thead><tr><th>Email / intended role</th><th>Status</th><th>Bound account</th><th>Expires</th></tr></thead><tbody><tr v-for="row in snapshot.requests" :key="row.id"><td>{{ row.email }}<br>{{ row.role }}</td><td>{{ row.status }}</td><td class="cqs-account-id">{{ row.bound_user || 'Trusted identity review pending' }}</td><td>{{ new Date(row.expires_at).toLocaleString() }}</td></tr><tr v-if="!snapshot.requests.length"><td colspan="4">No staff review requests.</td></tr></tbody></table></div>
      </section>
      <section v-if="tab==='counters'" class="cqs-card"><h2>Five fixed service counters</h2><div class="cqs-counter-admin-grid"><section v-for="counter in counters" :key="counter.id" class="cqs-card"><h3>{{ counter.label }} · {{ fixedCodes[counter.number-1] }}</h3><p>{{ config.services.find(s=>s.code===fixedCodes[counter.number-1])?.name }}</p><p>{{ counter.is_open?'Open':'Closed' }}</p><p class="cqs-caption">{{ config.staff_assignments.filter(a=>a.counter_id===counter.id).map(a=>snapshot.directory.find(x=>x.id===a.account_id)?.email || a.account_id).join(', ') || 'No assigned cashier' }}</p><button type="button" class="cqs-button cqs-button-outline" :disabled="locked" @click="editCounter(counter)">Edit assignments</button></section></div></section>
      <section v-if="tab==='reports'" class="cqs-card"><h2>Queue history · {{ snapshot.date }}</h2><div class="cqs-service-usage"><span v-for="row in snapshot.usage" :key="row.service"><strong>{{ row.service }}</strong> {{ row.total }} tickets</span></div><p class="cqs-caption">Exact database counts for the selected issuance date. No wait-time estimates or private student details. {{ snapshot.metrics.forfeited }} forfeited tickets.</p><p v-if="snapshot.history_more" class="cqs-notice">Showing the first 500 tickets. Totals above cover the full selected day; a complete export needs a separately reviewed paginated contract.</p><div class="cqs-table-scroll" tabindex="0" aria-label="Queue history"><table class="cqs-table"><thead><tr><th>Ticket</th><th>Date</th><th>Service</th><th>Status</th><th>Issued</th></tr></thead><tbody><tr v-for="row in snapshot.history" :key="row.ticket_id"><td>{{ ticketLabel(row) }}</td><td>{{ row.business_date }}</td><td>{{ row.service }}</td><td>{{ row.status }}</td><td>{{ new Date(row.issued_at).toLocaleTimeString() }}</td></tr><tr v-if="!snapshot.history.length"><td colspan="5">No tickets for this date.</td></tr></tbody></table></div></section>
    </template>
    <WorkspaceDialog v-if="dialog" :title="dialog.kind==='request'?'Request staff identity review':dialog.kind==='account'?'Review exact account access':'Configure fixed counter'" @close="dialog=null">
      <form v-if="dialog.kind==='request'" id="staff-request" @submit.prevent="request"><label class="cqs-field">Staff email<input v-model="email" type="email" maxlength="254" required autocomplete="off"></label><label class="cqs-field">Requested role<select v-model="role"><option>CASHIER</option><option>ADMIN</option></select></label><p class="cqs-notice">{{ targetByEmail?'An existing verified account matches. The request still requires trusted UUID/identity review and operator approval.':'No verified account matches. The person must personally sign in with Google before an operator can bind this request.' }}</p><p>No email will be sent. No role or account is created by this request.</p></form>
      <form v-else-if="dialog.kind==='account'" id="staff-account" @submit.prevent="saveAccount"><p><strong>{{ dialog.row.email || 'Unverified Google binding' }}</strong></p><p class="cqs-account-id">{{ dialog.row.id }}</p><label class="cqs-field">Database role<select v-model="role"><option>STUDENT</option><option>CASHIER</option><option>ADMIN</option></select></label><label><input v-model="enabled" type="checkbox"> Account enabled</label><p class="cqs-notice">Staff access requires this exact account's current operator approval and verified MFA. Last-ADMIN and unresolved-work checks are enforced by PostgreSQL. Revoking or disabling a cashier can remove its assignments.</p><p v-if="!canSaveAccount">This change requires current identity-bound approval/enrollment or operator review. No email-only promotion is allowed.</p></form>
      <form v-else id="counter-config" @submit.prevent="saveCounter"><h3>{{ dialog.row.label }} · {{ fixedCodes[dialog.row.number-1] }}</h3><label><input v-model="open" type="checkbox"> Counter open</label><fieldset><legend>Approved cashiers</legend><label v-for="row in snapshot.directory.filter(x=>eligible(x)||cashiers.includes(x.id))" :key="row.id" class="cqs-cashier-choice"><input v-model="cashiers" type="checkbox" :value="row.id" :disabled="!eligible(row)&&!cashiers.includes(row.id)">{{ row.email || row.id }}{{ eligible(row)?'':' — requires review; remove before saving' }}</label></fieldset><p class="cqs-caption">The assigned service cannot change. An open counter requires at least one approved, enabled cashier. Resolve a called ticket before reconfiguration.</p></form>
      <template #actions><button type="button" class="cqs-button cqs-button-outline" @click="dialog=null">Cancel</button><button type="submit" class="cqs-button cqs-button-primary" :form="dialog.kind==='request'?'staff-request':dialog.kind==='account'?'staff-account':'counter-config'" :disabled="dialog.kind==='request'?locked||!emailValid:dialog.kind==='account'?!canSaveAccount:locked||open&&!cashiers.length">{{ dialog.kind==='request'?'Record review request':'Confirm database change' }}</button></template>
    </WorkspaceDialog>
  </article>
</template>
